#pragma once
#include "windows.h"
inline constexpr UINT DXGI_FORMAT_B8G8R8A8_UNORM=1,D3D11_USAGE_STAGING=2,D3D11_USAGE_DEFAULT=3,D3D11_CPU_ACCESS_READ=4,D3D11_BIND_RENDER_TARGET=8,D3D11_MAP_READ=1,D3D11_MAP_FLAG_DO_NOT_WAIT=1;
struct D3D11_TEXTURE2D_DESC{UINT Width=0,Height=0,MipLevels=0,ArraySize=0,Format=0;struct {UINT Count=0,Quality=0;}SampleDesc;UINT Usage=0,CPUAccessFlags=0,BindFlags=0;};struct D3D11_BOX{UINT left,top,front,right,bottom,back;};struct D3D11_MAPPED_SUBRESOURCE{void* pData=nullptr;UINT RowPitch=0,DepthPitch=0;};
inline int fakeTextureCount=0;
struct ID3D11Texture2D{D3D11_TEXTURE2D_DESC desc;UINT pitch;std::vector<uint8_t> pixels;int references=1;bool busy=false;explicit ID3D11Texture2D(D3D11_TEXTURE2D_DESC d):desc(d),pitch(d.Width*4+(d.Usage==D3D11_USAGE_STAGING?64:0)),pixels(size_t(pitch)*d.Height){fakeTextureCount++;}void GetDesc(D3D11_TEXTURE2D_DESC* output){*output=desc;}void AddRef(){references++;}void Release(){if(--references==0){fakeTextureCount--;delete this;}}};
struct ID3D11RenderTargetView{ID3D11Texture2D* texture;void Release(){texture->Release();delete this;}};
struct ID3D11Device{std::vector<ID3D11Texture2D*> created;HRESULT CreateTexture2D(const D3D11_TEXTURE2D_DESC* d,void*,ID3D11Texture2D** output){*output=new ID3D11Texture2D(*d);created.push_back(*output);return S_OK;}HRESULT CreateRenderTargetView(ID3D11Texture2D* color,void*,ID3D11RenderTargetView** view){color->AddRef();*view=new ID3D11RenderTargetView{color};return S_OK;}};
struct ID3D11DeviceContext{int maps=0,copies=0,flushes=0;HRESULT Map(ID3D11Texture2D* t,UINT,UINT type,UINT flags,D3D11_MAPPED_SUBRESOURCE* mapped){assert(type==D3D11_MAP_READ&&flags==D3D11_MAP_FLAG_DO_NOT_WAIT);maps++;if(t->busy)return DXGI_ERROR_WAS_STILL_DRAWING;mapped->pData=t->pixels.data();mapped->RowPitch=t->pitch;return S_OK;}void Unmap(ID3D11Texture2D*,UINT){}void CopySubresourceRegion(ID3D11Texture2D* dest,UINT,UINT x,UINT y,UINT z,ID3D11Texture2D* source,UINT,const D3D11_BOX* box){assert(x==0&&y==0&&z==0&&box->back==1&&box->front==0&&box->right<=source->desc.Width&&box->bottom<=source->desc.Height&&box->right-box->left==dest->desc.Width&&box->bottom-box->top==dest->desc.Height);copies++;for(UINT row=0;row<dest->desc.Height;row++)std::memcpy(dest->pixels.data()+row*dest->pitch,source->pixels.data()+(box->top+row)*source->pitch+box->left*4,dest->desc.Width*4);}void Flush(){flushes++;}};
